    38→  },
    39→);
    40→
    41→export type ButtonProps = React.ComponentProps<"button"> &
    42→  VariantProps<typeof buttonVariants> & {
    43→    asChild?: boolean;
    44→  };
    45→
    46→function Button({
    47→  className,
    48→  variant,
    49→  size,
    50→  asChild = false,
    51→  ...props
    52→}: ButtonProps) {
    53→  const Comp = asChild ? Slot : "button";
    54→
    55→  return (
