    29→const SIDEBAR_COOKIE_NAME = "sidebar_state";
    30→const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
    31→const SIDEBAR_WIDTH = "16rem";
    32→const SIDEBAR_WIDTH_MOBILE = "18rem";
    33→const SIDEBAR_WIDTH_ICON = "3rem";
    34→const SIDEBAR_KEYBOARD_SHORTCUT = "b";
    35→
    36→type SidebarContextProps = {
    37→  state: "expanded" | "collapsed";
    38→  open: boolean;
    39→  setOpen: (open: boolean) => void;
    40→  openMobile: boolean;
    41→  setOpenMobile: (open: boolean) => void;
    42→  isMobile: boolean;
    43→  toggleSidebar: () => void;
    44→};
    45→
    46→const SidebarContext = React.createContext<SidebarContextProps | null>(null);
    47→
    48→function useSidebar() {
    49→  const context = React.useContext(SidebarContext);
    50→  if (!context) {
    51→    throw new Error("useSidebar must be used within a SidebarProvider.");
    52→  }
    53→
    54→  return context;
    55→}
    56→
    57→function SidebarProvider({
    58→  defaultOpen = true,
    59→  open: openProp,
    60→  onOpenChange: setOpenProp,
    61→  className,
    62→  style,
    63→  children,
    64→  ...props
    65→}: React.ComponentProps<"div"> & {
    66→  defaultOpen?: boolean;
    67→  open?: boolean;
    68→  onOpenChange?: (open: boolean) => void;
    69→}) {
    70→  const isMobile = useIsMobile();
    71→  const [openMobile, setOpenMobile] = React.useState(false);
    72→
    73→  // This is the internal state of the sidebar.
    74→  // We use openProp and setOpenProp for control from outside the component.
    75→  const [_open, _setOpen] = React.useState(defaultOpen);
    76→  const open = openProp ?? _open;
    77→
    78→  const setOpen = React.useCallback(
    79→    (value: boolean | ((value: boolean) => boolean)) => {
    80→      const openState = typeof value === "function" ? value(open) : value;
    81→      if (setOpenProp) {
    82→        setOpenProp(openState);
    83→      } else {
    84→        _setOpen(openState);
    85→      }
    86→
    87→      // This sets the cookie to keep the sidebar state.
    88→      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    89→    },
    90→    [setOpenProp, open],
    91→  );
    92→
    93→  // Helper to toggle the sidebar.
    94→  const toggleSidebar = React.useCallback(() => {
    95→    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
    96→  }, [isMobile, setOpen, setOpenMobile]);
    97→
    98→  // Adds a keyboard shortcut to toggle the sidebar.
    99→  React.useEffect(() => {
   100→    const handleKeyDown = (event: KeyboardEvent) => {
   101→      if (
   102→        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
   103→        (event.metaKey || event.ctrlKey)
   104→      ) {
   105→        event.preventDefault();
   106→        toggleSidebar();
   107→      }
   108→    };
   109→
   110→    window.addEventListener("keydown", handleKeyDown);
   111→    return () => window.removeEventListener("keydown", handleKeyDown);
   112→  }, [toggleSidebar]);
   113→
   114→  // Initialize sidebar state from cookie when component mounts
   115→  React.useEffect(() => {
   116→    // Only run on client-side
   117→    if (typeof document !== "undefined") {
   118→      const cookies = document.cookie.split(";");
   119→      const sidebarCookie = cookies.find((cookie) =>
   120→        cookie.trim().startsWith(`${SIDEBAR_COOKIE_NAME}=`),
   121→      );
   122→
   123→      if (sidebarCookie) {
   124→        const cookieValue = sidebarCookie.split("=")[1];
   125→        const isOpen = cookieValue === "true";
   126→
   127→        // Only update if we're not controlled externally
   128→        if (setOpenProp === undefined) {
   129→          _setOpen(isOpen);
   130→        }
   131→      }
   132→    }
   133→  }, [setOpenProp]);
   134→
   135→  // We add a state so that we can do data-state="expanded" or "collapsed".
   136→  // This makes it easier to style the sidebar with Tailwind classes.
   137→  const state = open ? "expanded" : "collapsed";
   138→
   139→  const contextValue = React.useMemo<SidebarContextProps>(
   140→    () => ({
   141→      state,
   142→      open,
   143→      setOpen,
   144→      isMobile,
   145→      openMobile,
   146→      setOpenMobile,
   147→      toggleSidebar,
   148→    }),
   149→    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
   150→  );
   151→
   152→  return (
   153→    <SidebarContext.Provider value={contextValue}>
   154→      <TooltipProvider delayDuration={0}>
   155→        <div
   156→          data-slot="sidebar-wrapper"
   157→          style={
   158→            {
   159→              "--sidebar-width": SIDEBAR_WIDTH,
   160→              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
   161→              ...style,
   162→            } as React.CSSProperties
   163→          }
   164→          className={cn(
   165→            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
   166→            className,
   167→          )}
   168→          {...props}
   169→        >
   170→          {children}
   171→        </div>
   172→      </TooltipProvider>
   173→    </SidebarContext.Provider>
   174→  );
   175→}
