   177→function Sidebar({
   178→  side = "left",
   179→  variant = "sidebar",
   180→  collapsible = "offcanvas",
   181→  className,
   182→  children,
   183→  ...props
   184→}: React.ComponentProps<"div"> & {
   185→  side?: "left" | "right";
   186→  variant?: "sidebar" | "floating" | "inset";
   187→  collapsible?: "offcanvas" | "icon" | "none";
   188→}) {
   189→  const { isMobile, state, openMobile, setOpenMobile } = useSidebar();
   190→
   191→  if (collapsible === "none") {
   192→    return (
   193→      <div
   194→        data-slot="sidebar"
   195→        className={cn(
   196→          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
   197→          className,
   198→        )}
   199→        {...props}
   200→      >
