   217→            } as React.CSSProperties
   218→          }
   219→          side={side}
   220→        >
   221→          <SheetHeader className="sr-only">
   222→            <SheetTitle>Sidebar</SheetTitle>
   223→            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
   224→          </SheetHeader>
   225→          <div className="flex size-full flex-col">{children}</div>
   226→        </SheetContent>
   227→      </Sheet>
   228→    );
   229→  }
   230→
   231→  return (
   232→    <div
   233→      className="text-sidebar-foreground group peer hidden md:block"
   234→      data-state={state}
   235→      data-collapsible={state === "collapsed" ? collapsible : ""}
   236→      data-variant={variant}
   237→      data-side={side}
   238→      data-slot="sidebar"
   239→    >
   240→      {/* This is what handles the sidebar gap on desktop */}
   241→      <div
   242→        data-slot="sidebar-gap"
   243→        className={cn(
   244→          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
   245→          "group-data-[collapsible=offcanvas]:w-0",
   246→          "group-data-[side=right]:rotate-180",
   247→          variant === "floating" || variant === "inset"
   248→            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
   249→            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)",
   250→        )}
   251→      />
   252→      <div
   253→        data-slot="sidebar-container"
   254→        className={cn(
   255→          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear md:flex",
   256→          side === "left"
   257→            ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
   258→            : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
   259→          // Adjust the padding for floating and inset variants.
   260→          variant === "floating" || variant === "inset"
   261→            ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
   262→            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
   263→          className,
   264→        )}
   265→        {...props}
   266→      >
   267→        <div
   268→          data-sidebar="sidebar"
   269→          data-slot="sidebar-inner"
   270→          className="bg-sidebar group-data-[variant=floating]:border-sidebar-border flex size-full flex-col group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:shadow-sm"
   271→        >
   272→          {children}
   273→        </div>
   274→      </div>
   275→    </div>
   276→  );
   277→}
