     1→"use client";
     2→
     3→import * as React from "react";
     4→import { Check, ChevronDown, X } from "lucide-react";
     5→import { cn } from "@/lib/utils";
     6→import { Badge } from "@/components/ui/badge";
     7→import { Button } from "@/components/ui/button";
     8→import {
     9→  Command,
    10→  CommandEmpty,
    11→  CommandGroup,
    12→  CommandInput,
    13→  CommandItem,
    14→} from "@/components/ui/command";
    15→import {
    16→  Popover,
    17→  PopoverContent,
    18→  PopoverTrigger,
    19→} from "@/components/ui/popover";
    20→
    21→export type Option = {
    22→  label: string;
    23→  value: string;
    24→  icon?: React.ComponentType<{ className?: string }>;
    25→};
    26→
    27→type MultiSelectProps = {
    28→  options: Option[];
    29→  selected: string[];
    30→  onChange: (selected: string[]) => void;
    31→  placeholder?: string;
    32→  className?: string;
    33→  disabled?: boolean;
    34→  maxCount?: number;
    35→  modalPopover?: boolean;
    36→  asChild?: boolean;
    37→  animation?: number;
    38→};
    39→
    40→export function MultiSelect({
    41→  options,
    42→  selected,
    43→  onChange,
    44→  placeholder = "Sélectionner...",
    45→  className,
    46→  disabled = false,
    47→  maxCount = 3,
    48→  modalPopover = false,
    49→  asChild: _asChild = false,
    50→  animation = 0,
    51→}: MultiSelectProps) {
    52→  const [open, setOpen] = React.useState(false);
    53→  const [inputValue, setInputValue] = React.useState("");
    54→
    55→  const handleUnselect = React.useCallback(
    56→    (value: string) => {
    57→      onChange(selected.filter((s) => s !== value));
    58→    },
    59→    [onChange, selected],
    60→  );
    61→
    62→  const handleKeyDown = React.useCallback(
    63→    (e: React.KeyboardEvent<HTMLDivElement>) => {
    64→      const input = e.target as HTMLInputElement;
    65→      if (input.value === "" && selected.length > 0) {
    66→        if (e.key === "Delete" || e.key === "Backspace") {
    67→          onChange(selected.slice(0, -1));
    68→        }
    69→      }
    70→      if (e.key === "Escape") {
    71→        input.blur();
    72→      }
    73→    },
    74→    [onChange, selected],
    75→  );
    76→
    77→  const selectables = options.filter(
    78→    (option) => !selected.includes(option.value),
    79→  );
    80→
    81→  return (
    82→    <Popover open={open} onOpenChange={setOpen} modal={modalPopover}>
    83→      <PopoverTrigger asChild>
    84→        <Button
    85→          variant="outline"
    86→          role="combobox"
    87→          aria-expanded={open}
    88→          className={cn(
    89→            "h-auto min-h-[2.5rem] w-full justify-between text-left font-normal",
    90→            className,
    91→          )}
    92→          disabled={disabled}
    93→          onClick={() => setOpen(!open)}
    94→        >
    95→          <div className="mr-2 flex min-h-[1.25rem] flex-1 flex-wrap gap-1">
    96→            {selected.length === 0 && (
    97→              <span className="text-muted-foreground py-1">{placeholder}</span>
    98→            )}
    99→            {selected.slice(0, maxCount).map((value) => {
   100→              const option = options.find((o) => o.value === value);
   101→              const IconComponent = option?.icon;
   102→              return (
   103→                <Badge
   104→                  variant="secondary"
   105→                  key={value}
   106→                  className="max-w-[120px] truncate px-2 py-0.5 text-xs"
   107→                  style={{
   108→                    animationDuration: `${animation}s`,
   109→                  }}
   110→                  title={option?.label}
   111→                >
   112→                  {IconComponent && (
   113→                    <IconComponent className="mr-1 h-3 w-3 flex-shrink-0" />
   114→                  )}
   115→                  <span className="truncate">{option?.label}</span>
   116→                  <span
   117→                    className="ring-offset-background focus:ring-ring ml-1 flex-shrink-0 cursor-pointer rounded-full outline-none focus:ring-2 focus:ring-offset-2"
   118→                    onKeyDown={(e) => {
   119→                      if (e.key === "Enter") {
   120→                        handleUnselect(value);
   121→                      }
   122→                    }}
   123→                    onMouseDown={(e) => {
   124→                      e.preventDefault();
   125→                      e.stopPropagation();
   126→                    }}
   127→                    onClick={() => handleUnselect(value)}
   128→                  >
   129→                    <X className="text-muted-foreground hover:text-foreground h-3 w-3" />
   130→                  </span>
   131→                </Badge>
   132→              );
   133→            })}
   134→            {selected.length > maxCount && (
   135→              <Badge
   136→                variant="secondary"
   137→                className="px-2 py-0.5 text-xs"
   138→                style={{
   139→                  animationDuration: `${animation}s`,
   140→                }}
   141→              >
   142→                {`+ ${selected.length - maxCount} plus`}
   143→              </Badge>
   144→            )}
   145→          </div>
   146→          <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
   147→        </Button>
   148→      </PopoverTrigger>
   149→      <PopoverContent
   150→        className="w-[--radix-popover-trigger-width] max-w-[--radix-popover-content-available-width] p-0"
   151→        align="start"
   152→      >
   153→        <Command>
   154→          <CommandInput
   155→            placeholder="Rechercher..."
   156→            value={inputValue}
   157→            onValueChange={setInputValue}
   158→            onKeyDown={handleKeyDown}
   159→          />
   160→          <CommandEmpty>Aucun résultat trouvé.</CommandEmpty>
   161→          <CommandGroup className="max-h-64 overflow-auto">
   162→            {selectables.map((option) => {
   163→              const IconComponent = option.icon;
   164→              return (
   165→                <CommandItem
   166→                  key={option.value}
   167→                  onSelect={() => {
   168→                    onChange([...selected, option.value]);
   169→                    setInputValue("");
   170→                  }}
   171→                >
   172→                  <Check
   173→                    className={cn(
   174→                      "mr-2 h-4 w-4",
   175→                      selected.includes(option.value)
   176→                        ? "opacity-100"
   177→                        : "opacity-0",
   178→                    )}
   179→                  />
   180→                  {IconComponent && (
   181→                    <IconComponent className="text-muted-foreground mr-2 h-4 w-4" />
   182→                  )}
   183→                  {option.label}
   184→                </CommandItem>
   185→              );
   186→            })}
   187→          </CommandGroup>
   188→        </Command>
   189→      </PopoverContent>
   190→    </Popover>
   191→  );
   192→}
   193→

