     1→"use client";
     2→
     3→import { useState, useEffect, useCallback } from "react";
     4→import { Check, ChevronDown, MapPin } from "lucide-react";
     5→import { cn } from "@/lib/utils";
     6→import { Button } from "@/components/ui/button";
     7→import {
     8→  Command,
     9→  CommandEmpty,
    10→  CommandGroup,
    11→  CommandInput,
    12→  CommandItem,
    13→  CommandList,
    14→} from "@/components/ui/command";
    15→import {
    16→  Popover,
    17→  PopoverContent,
    18→  PopoverTrigger,
    19→} from "@/components/ui/popover";
    20→import type { MoteurImmoCity } from "@/lib/moteurimmo/types";
    21→import { searchCitiesAction } from "@/features/properties/city-autocomplete.action";
    22→import { useDebounce } from "@/hooks/use-debounce";
    23→
    24→type CityComboboxProps = {
    25→  value?: MoteurImmoCity | null;
    26→  onValueChange: (city: MoteurImmoCity | null) => void;
    27→  placeholder?: string;
    28→  className?: string;
    29→};
    30→
    31→export function CityCombobox({
    32→  value,
    33→  onValueChange,
    34→  placeholder = "Sélectionner une ville...",
    35→  className,
    36→}: CityComboboxProps) {
    37→  const [open, setOpen] = useState(false);
    38→  const [searchQuery, setSearchQuery] = useState("");
    39→  const [cities, setCities] = useState<MoteurImmoCity[]>([]);
    40→  const [isLoading, setIsLoading] = useState(false);
    41→  const [error, setError] = useState<string | null>(null);
    42→
    43→  const debouncedSearchQuery = useDebounce(searchQuery, 300);
    44→
    45→  const searchCities = useCallback(async (query: string) => {
    46→    if (!query || query.length < 2) {
    47→      setCities([]);
    48→      return;
    49→    }
    50→
    51→    setIsLoading(true);
    52→    setError(null);
    53→
    54→    try {
    55→      const result = await searchCitiesAction(query);
    56→
    57→      if (result.error) {
    58→        setError(result.error);
    59→        setCities([]);
    60→      } else {
    61→        setCities(result.cities);
    62→      }
    63→    } catch {
    64→      setError("Erreur lors de la recherche");
    65→      setCities([]);
    66→    } finally {
    67→      setIsLoading(false);
    68→    }
    69→  }, []);
    70→
    71→  useEffect(() => {
    72→    void searchCities(debouncedSearchQuery);
    73→  }, [debouncedSearchQuery, searchCities]);
    74→
    75→  const handleSelect = (city: MoteurImmoCity) => {
    76→    onValueChange(city);
    77→    setOpen(false);
    78→    // Clear search after selection for multi-select mode
    79→    setSearchQuery("");
    80→    setCities([]);
    81→  };
    82→
    83→  const handleClear = () => {
    84→    onValueChange(null);
    85→    setSearchQuery("");
    86→    setCities([]);
    87→  };
    88→
    89→  const displayValue = value
    90→    ? `${value.name} (${value.postalCode})`
    91→    : placeholder;
    92→
    93→  return (
    94→    <Popover open={open} onOpenChange={setOpen}>
    95→      <PopoverTrigger asChild>
    96→        <Button
    97→          variant="outline"
    98→          role="combobox"
    99→          aria-expanded={open}
   100→          className={cn("justify-between", className)}
   101→        >
   102→          <div className="flex items-center gap-2">
   103→            <MapPin className="text-muted-foreground h-4 w-4" />
   104→            <span className={cn("truncate", !value && "text-muted-foreground")}>
   105→              {displayValue}
   106→            </span>
   107→          </div>
   108→          <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
   109→        </Button>
   110→      </PopoverTrigger>
   111→      <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0">
   112→        <Command>
   113→          <CommandInput
   114→            placeholder="Rechercher une ville..."
   115→            value={searchQuery}
   116→            onValueChange={setSearchQuery}
   117→          />
   118→          <CommandList>
   119→            {isLoading && <CommandEmpty>Recherche en cours...</CommandEmpty>}
   120→            {error && (
   121→              <CommandEmpty className="text-destructive">{error}</CommandEmpty>
   122→            )}
   123→            {!isLoading &&
   124→              !error &&
   125→              cities.length === 0 &&
   126→              searchQuery.length >= 2 && (
   127→                <CommandEmpty>Aucune ville trouvée</CommandEmpty>
   128→              )}
   129→            {!isLoading && !error && searchQuery.length < 2 && (
   130→              <CommandEmpty>Tapez au moins 2 caractères</CommandEmpty>
   131→            )}
   132→            {cities.length > 0 && (
   133→              <CommandGroup>
   134→                {value && (
   135→                  <CommandItem
   136→                    value="clear"
   137→                    onSelect={handleClear}
   138→                    className="text-muted-foreground"
   139→                  >
   140→                    Effacer la sélection
   141→                  </CommandItem>
   142→                )}
   143→                {cities.map((city) => (
   144→                  <CommandItem
   145→                    key={`${city.inseeCode}-${city.postalCode}`}
   146→                    value={`${city.name} ${city.postalCode}`}
   147→                    onSelect={() => handleSelect(city)}
   148→                    className="flex items-center justify-between"
   149→                  >
   150→                    <div className="flex items-center gap-2">
   151→                      <MapPin className="text-muted-foreground h-4 w-4" />
   152→                      <div>
   153→                        <div className="font-medium">{city.name}</div>
   154→                        <div className="text-muted-foreground text-sm">
   155→                          {city.postalCode} • {city.departmentName} (
   156→                          {city.departmentCode})
   157→                        </div>
   158→                      </div>
   159→                    </div>
   160→                    <Check
   161→                      className={cn(
   162→                        "ml-auto h-4 w-4",
   163→                        value?.inseeCode === city.inseeCode &&
   164→                          value.postalCode === city.postalCode
   165→                          ? "opacity-100"
   166→                          : "opacity-0",
   167→                      )}
   168→                    />
   169→                  </CommandItem>
   170→                ))}
   171→              </CommandGroup>
   172→            )}
   173→          </CommandList>
   174→        </Command>
   175→      </PopoverContent>
   176→    </Popover>
   177→  );
   178→}
