    15→} from "react-hook-form";
    16→import {
    17→  Controller,
    18→  FormProvider,
    19→  useForm,
    20→  useFormContext,
    21→  useFormState,
    22→  type ControllerProps,
    23→  type FieldPath,
    24→  type FieldValues,
    25→} from "react-hook-form";
    26→import type { TypeOf, ZodSchema } from "zod";
    27→
    28→export type FormProps<T extends FieldValues> = Omit<
    29→  React.ComponentProps<"form">,
    30→  "onSubmit"
    31→> & {
    32→  form: UseFormReturn<T>;
    33→  onSubmit: SubmitHandler<T>;
    34→  disabled?: boolean;
    35→  submitOnBlur?: boolean;
    36→};
    37→
    38→const Form = <T extends FieldValues>({
    39→  form,
    40→  onSubmit,
    41→  children,
    42→  className,
    43→  disabled,
    44→  submitOnBlur = false,
    45→  ...props
    46→}: FormProps<T>) => {
    47→  const debouncedBlurSubmit = useDebounceFn(() => {
    48→    void form.handleSubmit(onSubmit)();
    49→  }, 500);
    50→
    51→  return (
    52→    <FormProvider {...form}>
    53→      <form
    54→        onSubmit={form.handleSubmit(onSubmit)}
    55→        onBlur={async () => {
    56→          if (submitOnBlur) {
    57→            debouncedBlurSubmit();
    58→          }
    59→        }}
    60→        {...props}
    61→        className={className}
    62→      >
    63→        <fieldset
    64→          disabled={disabled ?? form.formState.isSubmitting}
    65→          className={className}
    66→        >
    67→          {children}
    68→        </fieldset>
    69→      </form>
    70→    </FormProvider>
    71→  );
    72→};
    73→
    74→type FormFieldContextValue<
    75→  TFieldValues extends FieldValues = FieldValues,
    76→  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
    77→> = {
    78→  name: TName;
    79→};
    80→
    81→const FormFieldContext = React.createContext<FormFieldContextValue>(
    82→  {} as FormFieldContextValue,
    83→);
    84→
    85→const FormField = <
    86→  TFieldValues extends FieldValues = FieldValues,
    87→  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
    88→>({
    89→  ...props
    90→}: ControllerProps<TFieldValues, TName>) => {
    91→  return (
    92→    <FormFieldContext.Provider value={{ name: props.name }}>
    93→      <Controller {...props} />
    94→    </FormFieldContext.Provider>
    95→  );
    96→};
    97→
    98→const useFormField = () => {
    99→  const fieldContext = React.useContext(FormFieldContext);
   100→  const itemContext = React.useContext(FormItemContext);
   101→  const { getFieldState } = useFormContext();
   102→  const formState = useFormState({ name: fieldContext.name });
   103→  const fieldState = getFieldState(fieldContext.name, formState);
   104→
   105→  if (!fieldContext) {
   106→    throw new Error("useFormField should be used within <FormField>");
   107→  }
   108→
   109→  const { id } = itemContext;
   110→
   111→  return {
   112→    id,
   113→    name: fieldContext.name,
   114→    formItemId: `${id}-form-item`,
   115→    formDescriptionId: `${id}-form-item-description`,
   116→    formMessageId: `${id}-form-item-message`,
   117→    ...fieldState,
   118→  };
   119→};
   120→
   121→type FormItemContextValue = {
   122→  id: string;
   123→};
   124→
   125→const FormItemContext = React.createContext<FormItemContextValue>(
   126→  {} as FormItemContextValue,
   127→);
   128→
   129→function FormItem({ className, ...props }: React.ComponentProps<"div">) {
   130→  const id = React.useId();
   131→
   132→  return (
   133→    <FormItemContext.Provider value={{ id }}>
   134→      <div
   135→        data-slot="form-item"
   136→        className={cn("grid gap-2", className)}
   137→        {...props}
   138→      />
   139→    </FormItemContext.Provider>
   140→  );
   141→}
   142→
   143→function FormLabel({
   144→  className,
   145→  ...props
   146→}: React.ComponentProps<typeof LabelPrimitive.Root>) {
   147→  const { error, formItemId } = useFormField();
   148→
   149→  return (
   150→    <Label
   151→      data-slot="form-label"
   152→      data-error={!!error}
   153→      className={cn("data-[error=true]:text-destructive", className)}
   154→      htmlFor={formItemId}
   155→      {...props}
   156→    />
   157→  );
   158→}
   159→
   160→function FormControl({ ...props }: React.ComponentProps<typeof Slot>) {
   161→  const { error, formItemId, formDescriptionId, formMessageId } =
   162→    useFormField();
   163→
   164→  return (
   165→    <Slot
   166→      data-slot="form-control"
   167→      id={formItemId}
   168→      aria-describedby={
   169→        !error
   170→          ? `${formDescriptionId}`
   171→          : `${formDescriptionId} ${formMessageId}`
   172→      }
   173→      aria-invalid={!!error}
   174→      {...props}
   175→    />
   176→  );
   177→}
   178→
   179→function FormDescription({ className, ...props }: React.ComponentProps<"p">) {
   180→  const { formDescriptionId } = useFormField();
   181→
   182→  return (
   183→    <p
   184→      data-slot="form-description"
   185→      id={formDescriptionId}
   186→      className={cn("text-muted-foreground text-sm", className)}
   187→      {...props}
   188→    />
   189→  );
   190→}
   191→
   192→function FormMessage({ className, ...props }: React.ComponentProps<"p">) {
   193→  const { error, formMessageId } = useFormField();
   194→  const body = error ? String(error.message ?? "") : props.children;
   195→
   196→  if (!body) {
   197→    return null;
   198→  }
   199→
   200→  return (
   201→    <p
   202→      data-slot="form-message"
   203→      id={formMessageId}
   204→      className={cn("text-destructive text-sm", className)}
   205→      {...props}
   206→    >
   207→      {body}
   208→    </p>
   209→  );
   210→}
   211→
   212→type UseZodFormProps<Z extends ZodSchema> = Exclude<
   213→  UseFormProps<TypeOf<Z>>,
   214→  "resolver"
   215→> & {
   216→  schema: Z;
   217→};
   218→
   219→const useZodForm = <Z extends ZodSchema>({
   220→  schema,
   221→  ...formProps
   222→}: UseZodFormProps<Z>) =>
   223→  useForm({
   224→    ...formProps,
   225→    resolver: zodResolver(schema),
   226→  });
   227→
   228→export {
   229→  Form,
   230→  FormControl,
   231→  FormDescription,
   232→  FormField,
   233→  FormItem,
   234→  FormLabel,
   235→  FormMessage,
   236→  useFormField,
   237→  useZodForm,
   238→};
