     6→
     7→type SafeImageProps = {
     8→  src: string | null | undefined;
     9→  alt: string;
    10→  fill?: boolean;
    11→  width?: number;
    12→  height?: number;
    13→  className?: string;
    14→  sizes?: string;
    15→  priority?: boolean;
    16→};
    17→
    18→/**
    19→ * SafeImage - Image component that gracefully handles external images
    20→ * Shows a fallback UI when the image fails to load or domain is not configured
    21→ */
    22→export function SafeImage({
    23→  src,
    24→  alt,
    25→  fill = false,
    26→  width,
    27→  height,
    28→  className,
    29→  sizes,
    30→  priority = false,
    31→}: SafeImageProps) {
    32→  const [hasError, setHasError] = useState(false);
    33→  const [isLoading, setIsLoading] = useState(true);
    34→
    35→  // If no src provided, show fallback immediately
    36→  if (!src || hasError) {
    37→    return (
    38→      <div className={`bg-muted flex items-center justify-center ${className}`}>
    39→        <div className="text-muted-foreground flex flex-col items-center gap-2">
    40→          <Building2 className="h-8 w-8" />
    41→          <span className="text-center text-xs">Image non disponible</span>
    42→        </div>
    43→      </div>
    44→    );
    45→  }
    46→
    47→  return (
    48→    <>
    49→      {isLoading && (
    50→        <div className={`bg-muted animate-pulse ${className}`}>
    51→          <div className="flex h-full items-center justify-center">
    52→            <div className="border-primary h-4 w-4 animate-spin rounded-full border-2 border-t-transparent" />
    53→          </div>
    54→        </div>
    55→      )}
    56→      <Image
    57→        src={src}
    58→        alt={alt}
    59→        fill={fill}
    60→        width={width}
    61→        height={height}
    62→        className={`${className} ${isLoading ? "opacity-0" : "opacity-100"} transition-opacity duration-300`}
    63→        sizes={sizes}
    64→        priority={priority}
    65→        onLoad={() => setIsLoading(false)}
    66→        onError={() => {
    67→          setIsLoading(false);
    68→          setHasError(true);
    69→        }}
    70→        // Disable Next.js domain validation for external images
    71→        unoptimized={true}
    72→      />
    73→    </>
    74→  );
    75→}
