     1→"use client";
     2→
     3→import {
     4→  createContext,
     5→  useContext,
     6→  useEffect,
     7→  useState,
     8→  type ReactNode,
     9→} from "react";
    10→
    11→type ContextTheme = "b2c" | "b2b" | "default";
    12→
    13→type ContextThemeContextType = {
    14→  theme: ContextTheme;
    15→  isB2C: boolean;
    16→  isB2B: boolean;
    17→  setTheme: (theme: ContextTheme) => void;
    18→};
    19→
    20→const ContextThemeContext = createContext<ContextThemeContextType>({
    21→  theme: "default",
    22→  isB2C: false,
    23→  isB2B: false,
    24→  setTheme: () => {
    25→    // No-op - will be overridden by provider
    26→  },
    27→});
    28→
    29→type ContextThemeProviderProps = {
    30→  children: ReactNode;
    31→  defaultTheme?: ContextTheme;
    32→  forceTheme?: ContextTheme;
    33→};
    34→
    35→/**
    36→ * Context Theme Provider
    37→ * Automatically detects B2C/B2B context and applies appropriate theming
    38→ */
    39→export function ContextThemeProvider({
    40→  children,
    41→  defaultTheme = "default",
    42→  forceTheme,
    43→}: ContextThemeProviderProps) {
    44→  const [theme, setTheme] = useState<ContextTheme>(forceTheme ?? defaultTheme);
    45→
    46→  useEffect(() => {
    47→    if (forceTheme) {
    48→      setTheme(forceTheme);
    49→      return;
    50→    }
    51→
    52→    // TODO: Implement automatic detection based on user's accountType
    53→    // For now, we'll use the defaultTheme or manually set theme
    54→    setTheme(defaultTheme);
    55→  }, [forceTheme, defaultTheme]);
    56→
    57→  // Apply theme to document root
    58→  useEffect(() => {
    59→    const root = document.documentElement;
    60→
    61→    // Remove previous theme classes
    62→    root.classList.remove("theme-b2c", "theme-b2b", "theme-default");
    63→
    64→    // Add current theme class
    65→    root.classList.add(`theme-${theme}`);
    66→
    67→    // Set CSS custom properties based on theme
    68→    switch (theme) {
    69→      case "b2c":
    70→        // Warmer, emotional palette for consumers
    71→        root.style.setProperty("--context-primary", "hsl(221, 83%, 53%)"); // Warm blue
    72→        root.style.setProperty("--context-accent", "hsl(34, 100%, 50%)"); // Orange accent
    73→        root.style.setProperty("--context-secondary", "hsl(350, 89%, 60%)"); // Heart red
    74→        root.style.setProperty("--context-success", "hsl(142, 71%, 45%)"); // Green
    75→        root.style.setProperty("--context-radius", "12px"); // Rounded corners
    76→        root.style.setProperty("--context-spacing", "1.5rem"); // Generous spacing
    77→        root.style.setProperty(
    78→          "--context-shadow",
    79→          "0 4px 6px -1px rgb(0 0 0 / 0.1)",
    80→        ); // Soft shadows
    81→        break;
    82→      case "b2b":
    83→        // Professional, data-focused palette
    84→        root.style.setProperty("--context-primary", "hsl(215, 25%, 27%)"); // Professional dark blue
    85→        root.style.setProperty("--context-accent", "hsl(142, 71%, 45%)"); // Business green
    86→        root.style.setProperty("--context-secondary", "hsl(220, 13%, 69%)"); // Neutral gray
    87→        root.style.setProperty("--context-success", "hsl(142, 71%, 45%)"); // Green
    88→        root.style.setProperty("--context-radius", "6px"); // Sharp corners
    89→        root.style.setProperty("--context-spacing", "1rem"); // Compact spacing
    90→        root.style.setProperty(
    91→          "--context-shadow",
    92→          "0 1px 3px 0 rgb(0 0 0 / 0.1)",
    93→        ); // Subtle shadows
    94→        break;
    95→      default:
    96→        root.style.setProperty("--context-primary", "hsl(220, 13%, 91%)");
    97→        root.style.setProperty("--context-accent", "hsl(220, 13%, 69%)");
    98→        root.style.setProperty("--context-secondary", "hsl(220, 13%, 69%)");
    99→        root.style.setProperty("--context-success", "hsl(142, 71%, 45%)");
   100→        root.style.setProperty("--context-radius", "8px");
   101→        root.style.setProperty("--context-spacing", "1.25rem");
   102→        root.style.setProperty(
   103→          "--context-shadow",
   104→          "0 2px 4px 0 rgb(0 0 0 / 0.1)",
   105→        );
   106→        break;
   107→    }
   108→  }, [theme]);
   109→
   110→  const value = {
   111→    theme,
   112→    isB2C: theme === "b2c",
   113→    isB2B: theme === "b2b",
   114→    setTheme,
   115→  };
   116→
   117→  return (
   118→    <ContextThemeContext.Provider value={value}>
   119→      {children}
   120→    </ContextThemeContext.Provider>
   121→  );
   122→}
   123→
   124→/**
   125→ * Hook to use context theme
   126→ */
   127→export function useContextTheme() {
   128→  const context = useContext(ContextThemeContext);
   129→  return context;
   130→}
   131→

